// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
func newFlagSet(name string, opts *options) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
